/* TF-IDF nearest-neighbor classifier. Fitted weights are generated by train.py. */
(function(root){
 const tokens=s=>(s.toLowerCase().replaceAll('c++','cplusplus').replaceAll('c#','csharp').match(/[a-z0-9]+/g)||[]);
 const stop=new Set('a an the is are was were what who how do does did can could would should of to in on at for from about his he him your you me my i tell please this that and it they their which where when has have had sayan mandal know'.split(' '));
 function answer(model,query,previous=''){
   let terms=tokens(query); const all=terms.filter(t=>!stop.has(t));
   const fallback=model.knowledge.find(k=>k.id==='unknown');
   if (!all.length) return /\b(?:who|about)\b/i.test(query) && /\b(?:sayan|yourself|you|him)\b/i.test(query) ? model.knowledge.find(k=>k.id==='about') : fallback;
   const byId=id=>model.knowledge.find(k=>k.id===id);
   if (/\b(?:password|api key|phone number|passport number|salary|cgpa|girlfriend|home address|exact address|date of birth|religion|private information|semester|born|age|marital status|private key)\b/i.test(query)) return fallback;
   // Resolve short follow-ups for a previously selected project.
   if (previous && !['unknown','greeting','about'].includes(previous) && /^(?:and\s+)?(?:what(?:'s| is| are)?\s+(?:its|the)\s+|its\s+|the\s+)?(?:tech(?:nology)? stack|technologies|features|source code|github link|live demo|demo link|more details|tell me more|link)\s*[?.!]*$/i.test(query.trim())) return byId(previous)||fallback;
   if (/\b(?:this (?:chatbot|bot|assistant)|you trained|local model|chat private|this chatbot trained)\b/i.test(query)) return byId('localbot');
   // Distinctive project names are stronger signals than generic words like "stack".
   const names=[['MediMitra',/\bmedi\s*mitra\b/i],['AgroPulse',/\bagro\s*pulse\b/i],['SmartRoom',/\bsmart\s*(?:room|classroom)\b/i],['MediaDrop DevOps',/\bmedia\s*drop\b/i],["Sayan's Chatbot",/\bsayan(?:['’]s)?\s+chatbot\b/i],['Jarvis',/\bjarv[ie]s\b/i]];
   const matches=names.filter(([,r])=>r.test(query)); if(matches.length===1)return byId(matches[0][0])||fallback;
   if(matches.length>1)return {id:'projects',answer:matches.map(([id])=>byId(id).answer.split('\n\n')[0]).join('\n\n'),links:matches.flatMap(([id])=>byId(id).links.filter(l=>l.url.startsWith('https:')).map(l=>({label:id+' · '+l.label,url:l.url})))};
   if (/\b(?:cognifyz|broskieshub|aivariant)\b/i.test(query)) {const matches=['cognifyz','broskieshub','aivariant'].filter(id=>new RegExp('\\b'+id+'\\b','i').test(query));return byId(matches.length===1?matches[0]:'experience');}
   if (/\b(?:certificat(?:e|es|ion|ions)|credentials)\b/i.test(query)) return byId('certifications');
   if (/\b(?:college|university|degree|btech|graduat(?:e|ion)|school|qualification)\b/i.test(query)) return byId('education');
   if (/\b(?:internship|internships|interned|cognifyz|broskieshub|aivariant)\b/i.test(query)) return byId('experience');
   if (/\b(?:rust|golang|ruby|swift|kotlin|scala|cobol|haskell|elixir)\b/i.test(query)) return fallback;
   const known=all.filter(t=>Object.hasOwn(model.idf,t)); if(!known.length || known.length/all.length<0.35)return fallback;
   const v=Object.create(null); for(const w of all)if(Object.hasOwn(model.idf,w))v[w]=(v[w]||0)+model.idf[w];
   const norm=Math.hypot(...Object.values(v)); if(!norm)return fallback;
   let best=-1, score=0;
   for(const row of model.vectors){let sim=0; for(const [w,x] of Object.entries(v))if(Object.hasOwn(row.v,w))sim+=x*row.v[w]/norm; if(sim>score){score=sim;best=row.intent;}}
   return score>=0.33&&best>=0?model.knowledge[best]:fallback;
 }
 const api={answer}; if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.PortfolioChatEngine=api;
})(typeof globalThis!=='undefined'?globalThis:this);
